// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed params: an address 'from' and a uint256 v and an array length seed
    // We cannot fuzz an address to be a contract; so we deploy a helper Recorder that implements
    // the exact transferFrom(address,address,uint256) signature and records calls.
    function testFuzz_property(address from, uint256 v, uint8 tosCount) public {
        // keep tosCount small but allow zero to be excluded by contract's require
        uint8 n = tosCount;
        if (n == 0) n = 1; // ensure at least one recipient so call body executes

        // build array of recipient addresses; all point to our Recorder contract
        Recorder recorder = new Recorder();
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(recorder);
        }

        // Call transfer on c. The correct contract will call recorder.transferFrom(from, tos[i], v)
        // for each recipient; the recorder's log will record each call that matched selector.
        bool ok;
        try c.transfer(from, address(recorder), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ALL inputs the reference implementation will NOT revert
        // because it computes the correct selector and the Recorder implements that function and returns true.
        // The mutant that uses a wrong selector will fail to dispatch to Recorder.transferFrom(...)
        // and thus the low-level call will likely return false and cause a revert for some inputs.
        // We assert that the call succeeded (ok == true) and that the recorder observed exactly n calls
        // with the expected decoded arguments. This reading uses only the recorder's public getters
        // (which observe c's external behaviour), satisfying the requirement to observe c only via public surface.

        // Check that call succeeded
        assertTrue(ok);
        // Ensure recorder observed the expected number of calls
        assertTrue(recorder.count() == n);
        // Validate each recorded call matches the arguments c should have sent
        for (uint i = 0; i < n; i++) {
            (address r_from, address r_to, uint256 r_v) = recorder.calls(i);
            assertTrue(r_from == from);
            // r_to should equal tos[i] which is address(recorder)
            assertTrue(r_to == address(recorder));
            assertTrue(r_v == v);
        }
    }
}

// Recorder implements the exact signature transferFrom(address,address,uint256)
// so that a correct abi.encodeWithSelector(...) using that signature will dispatch here.
contract Recorder {
    struct Call { address from; address to; uint256 v; }
    Call[] public log_;

    // this matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        log_.push(Call({from: from, to: to, v: v}));
        return true;
    }

    // helper getters to read recorded data
    function count() external view returns (uint256) { return log_.length; }
    function calls(uint256 i) external view returns (address, address, uint256) {
        Call storage c = log_[i];
        return (c.from, c.to, c.v);
    }
}
